def distance(p1, p2):
    return math.sqrt((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2)

def point_to_line_distance(point, line):
    x0, y0 = point
    if line[0] == float('inf'):  # Vertical line
        return abs(x0 - line[1])
    else:
        m, c = line
        return abs(m * x0 - y0 + c) / math.sqrt(m**2 + 1)

def max_fruits_sliced(fruits):
    n = len(fruits)
    max_count = 0

    for i in range(n):
        for j in range(i + 1, n):
            x1, y1 = fruits[i]
            x2, y2 = fruits[j]

            if x1 == x2:  # Vertical line
                line = (float('inf'), x1)
            else:
                m = (y2 - y1) / (x2 - x1)
                c = y1 - m * x1
                line = (m, c)

            count = 0
            for fruit in fruits:
                if point_to_line_distance(fruit, line) <= 1:
                    count += 1

            max_count = max(max_count, count)

    return max_count

